-- Insert Quiz Questions for Lesson: Payments, Delivery and Order Emails

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 19 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 19 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'payments-delivery-order-emails' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson payments-delivery-order-emails not found in module 19';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where do you connect a payment provider?', 
    '["Contacts → Forms","Payments → Integrations","Sites → Stores","Marketing → Funnels"]'::jsonb,
    'Payments → Integrations',
    'Payment providers are connected under Payments → Integrations, separate from the store builder.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'True or False: Connecting a payment provider automatically delivers every kind of digital product correctly.', 
    '["False","True"]'::jsonb,
    'False',
    'False. Fulfillment and access must be configured for each product type and tested separately.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the danger of a successful charge with no product access?', 
    '["The payment provider will close your account immediately","It is not a successful customer experience and will lead to refunds and complaints","The customer might pay twice","The product will be automatically refunded"]'::jsonb,
    'It is not a successful customer experience and will lead to refunds and complaints',
    'A successful charge means nothing if the customer cannot access what they purchased. Always test the full delivery flow.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
