-- Insert Quiz Questions for Lesson: The Mystery Shopper Test

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 19 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 19 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'mystery-shopper-test' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson mystery-shopper-test not found in module 19';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How should you test a purchase safely?', 
    '["Use the payment provider''s documented test or sandbox method","Use a real credit card and hope for the best","Ask a customer to test for you","Skip testing and launch immediately"]'::jsonb,
    'Use the payment provider''s documented test or sandbox method',
    'Always use the payment provider''s documented test or sandbox method. Never guess—real charges and fees may apply.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do if a scorecard check does not apply to your product type?', 
    '["Replace it with a relevant fulfillment check","Skip the entire scorecard","Change your product to match the scorecard","Automatically award the point anyway"]'::jsonb,
    'Replace it with a relevant fulfillment check',
    'If a check is genuinely inapplicable, replace it with a relevant fulfillment check rather than automatically awarding a point.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you ask a colleague to test without prompting?', 
    '["To discover friction points a familiar user would miss","To verify they can follow instructions","To save time explaining the process","To train them as a backup administrator"]'::jsonb,
    'To discover friction points a familiar user would miss',
    'A fresh user will encounter friction points that you, as the builder, have become blind to. Their confusion reveals real problems.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
