-- Insert Quiz Questions for Lesson: Open for Business

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 19 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 19 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'open-for-business' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson open-for-business not found in module 19';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before accepting real customer payments?', 
    '["Hire a marketing agency","Add 100 products first","Complete a supported safe test and verify fulfillment","Publish without testing"]'::jsonb,
    'Complete a supported safe test and verify fulfillment',
    'Always complete a safe test checkout and verify delivery before accepting real customer payments.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where should you check the public store before launch?', 
    '["In the Store Builder preview only","In a private or incognito browser window","On your phone only","You do not need to check it"]'::jsonb,
    'In a private or incognito browser window',
    'Always check the public URL in a private/incognito window to see what actual customers will see.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the five-visitor challenge?', 
    '["A sales target of five customers in the first week","A discount for the first five buyers","A requirement to have five products before launch","Inviting five reviewers to answer three questions about clarity and usability"]'::jsonb,
    'Inviting five reviewers to answer three questions about clarity and usability',
    'The five-visitor challenge invites five friendly reviewers to look at your store and answer whether it is clear, confusing, and actionable.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
