-- Insert Quiz Questions for Lesson: Manage Orders and Improve the Store

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 19 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 19 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'manage-orders-improve-store' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson manage-orders-improve-store not found in module 19';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where can you review customer orders?', 
    '["Settings → My Profile","Marketing → Campaigns","Sites → Blogs","Payments → Orders"]'::jsonb,
    'Payments → Orders',
    'Customer orders and their status are reviewed under Payments → Orders.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do during your simple weekly review?', 
    '["Check orders, payment activity, respond to questions, and make one improvement","Delete all old products","Change your store name","Add 10 new products every week"]'::jsonb,
    'Check orders, payment activity, respond to questions, and make one improvement',
    'A simple weekly review includes checking orders, payment activity, responding to questions, reviewing performance, and making one clear improvement.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why must someone own the post-purchase customer experience?', 
    '["It automatically increases sales","It reduces the need for marketing","It is required by law","A store without order management will disappoint customers and damage reputation"]'::jsonb,
    'A store without order management will disappoint customers and damage reputation',
    'Without someone managing orders and support, customers will be left waiting, leading to refunds, complaints, and damaged reputation.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
